    #[test]
    fn derive_release_commit_decision_reports_head_mismatch_distinctly() {
        let actual_head = "a".repeat(40);
        let claimed_commit = "c".repeat(40);

        let runner = CountingBatchRunner {
            release_commit: actual_head,
            parent: "b".repeat(40),
