    /// A plan bumping exactly `package_name` (a `cargo:` package), so
    /// `derive_release_decision` produces a real, non-empty roster instead
    /// of failing on `ReleaseDecisionError::EmptyRoster` before the
    /// selection-validation logic under test ever runs.
    /// Fixed groups version in lockstep: narrowing to one member must keep its
    /// siblings, or a sibling's release artifact fails ArtifactSlotOutsideDecision
    /// and a bumped sibling is left unpublished (the 0.6-0.7 failure shape).
    #[test]
    fn selecting_one_fixed_group_member_retains_its_lockstep_siblings() {
        let runner = CountingBatchRunner {
            release_commit: "a".repeat(40),
            parent: "b".repeat(40),
            decision_json: String::new(),
            name_status: String::new(),
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };
        let mut workspace = fixture_workspace(
            &runner,
            vec![
                publishing_cargo_package("cli"),
                cargo_package("plugin"),
                cargo_package("other"),
            ],
        );
        let group = callisto_model::GroupName("workspace".to_string());
        for name in ["cli", "plugin"] {
            workspace.config.groups.fixed_of.insert(
                callisto_model::PackageId::parse(&format!("cargo:{name}")).unwrap(),
                group.clone(),
            );
        }
        let bump = |name: &str, reason: BumpReason| crate::PlannedBump {
            package: callisto_model::PackageId::parse(&format!("cargo:{name}")).unwrap(),
            from: Version::semver(1, 0, 0),
            to: Version::semver(1, 1, 0),
            severity: callisto_model::Severity::Minor,
            governed_by: None,
            reason: Some(reason),
            writes: vec![],
        };
        let plan = VersionPlan {
            bumps: vec![
                bump("cli", BumpReason::Changeset { changesets: vec![] }),
                bump("plugin", BumpReason::FixedGroupUnion { group: group.clone() }),
                bump("other", BumpReason::Changeset { changesets: vec![] }),
            ],
            ..Default::default()
        };
        let cli = ReleasePackageId::new(Ecosystem::Cargo, "cli").unwrap();

        let decision = derive_selected_release_decision(&workspace, &plan, &[cli]).unwrap();

        let released: Vec<String> = decision.entries.iter().map(|e| e.package.to_string()).collect();
        assert!(
            released.iter().any(|p| p.ends_with("plugin")),
            "fixed sibling dropped: {released:?}"
        );
        assert!(
            !released.iter().any(|p| p.ends_with("other")),
            "unrelated package kept: {released:?}"
        );
    }

    fn plan_bumping(package_name: &str) -> VersionPlan {
        VersionPlan {
            bumps: vec![crate::PlannedBump {
                package: callisto_model::PackageId::parse(&format!("cargo:{package_name}")).unwrap(),
                from: Version::semver(1, 0, 0),
                to: Version::semver(1, 1, 0),
                severity: callisto_model::Severity::Minor,
                governed_by: None,
                reason: Some(BumpReason::Changeset { changesets: vec![] }),
                writes: vec![],
            }],
            ..Default::default()
        }
    }

    /// A duplicate `--package` selection must report
    /// `ReleaseSelectionInvalid{reason: Duplicate}` naming the duplicated
    /// package, not the fieldless `ReleaseIntentStale`.
    #[test]
    fn derive_selected_release_decision_reports_duplicate_selection_distinctly() {
        let package = ReleasePackageId::new(Ecosystem::Cargo, "pkg-a").unwrap();
        let runner = CountingBatchRunner {
            release_commit: "a".repeat(40),
            parent: "b".repeat(40),
            decision_json: String::new(),
            name_status: String::new(),
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };
        let workspace = fixture_workspace(&runner, vec![cargo_package("pkg-a")]);
        let plan = plan_bumping("pkg-a");

        let err = derive_selected_release_decision(&workspace, &plan, &[package.clone(), package.clone()]).unwrap_err();
        match err {
            GraphError::ReleaseSelectionInvalid {
                package: reported,
                reason,
            } => {
                assert_eq!(reported, package);
                assert_eq!(reason, ReleaseSelectionInvalidReason::Duplicate);
            }
            other => panic!("expected ReleaseSelectionInvalid{{Duplicate}}, got {other:?}"),
        }
    }

    fn empty_runner() -> CountingBatchRunner {
        CountingBatchRunner {
            release_commit: "a".repeat(40),
            parent: "b".repeat(40),
            decision_json: String::new(),
            name_status: String::new(),
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        }
    }

    fn selection_error(workspace_packages: Vec<Package>, bumped: &str, selection: &str) -> GraphError {
        let runner = empty_runner();
        let workspace = fixture_workspace(&runner, workspace_packages);
        let selection = ReleasePackageId::new(Ecosystem::Cargo, selection).unwrap();
        derive_selected_release_decision(&workspace, &plan_bumping(bumped), std::slice::from_ref(&selection))
            .unwrap_err()
    }

    /// A workspace package with no pending release is `NotARelease`.
    #[test]
    fn selection_that_is_not_a_release_candidate_reports_not_a_release() {
        let err = selection_error(
            vec![publishing_cargo_package("pkg-a"), publishing_cargo_package("pkg-b")],
            "pkg-b",
            "pkg-a",
        );
        assert!(
            matches!(
                &err,
                GraphError::ReleaseSelectionInvalid { package, reason: ReleaseSelectionInvalidReason::NotARelease }
                    if package.name() == "pkg-a"
            ),
            "{err:?}"
        );
    }

    /// A release candidate with nothing to dispatch is `NoDispatchableTarget`.
    #[test]
    fn release_candidate_without_publish_target_reports_no_dispatchable_target() {
        let err = selection_error(vec![cargo_package("pkg-a")], "pkg-a", "pkg-a");
        assert!(
            matches!(
                &err,
                GraphError::ReleaseSelectionInvalid { package, reason: ReleaseSelectionInvalidReason::NoDispatchableTarget }
                    if package.name() == "pkg-a"
            ),
            "{err:?}"
        );
    }

    /// Selection is by exact `ecosystem/name`; a same-named package in another
    /// ecosystem, or a name absent from the workspace, never matches.
    #[test]
    fn selection_matches_exact_ecosystem_and_name_only() {
        let runner = empty_runner();
        let workspace = fixture_workspace(&runner, vec![publishing_cargo_package("pkg-a")]);
        for selection in [
            ReleasePackageId::new(Ecosystem::Npm, "pkg-a").unwrap(),
            ReleasePackageId::new(Ecosystem::Cargo, "pkg").unwrap(),
        ] {
            let err = derive_selected_release_decision(&workspace, &plan_bumping("pkg-a"), &[selection]).unwrap_err();
            assert!(matches!(err, GraphError::UnknownPackage { .. }), "{err:?}");
        }
        let exact = ReleasePackageId::new(Ecosystem::Cargo, "pkg-a").unwrap();
        let decision =
            derive_selected_release_decision(&workspace, &plan_bumping("pkg-a"), std::slice::from_ref(&exact)).unwrap();
        assert_eq!(decision.entries.len(), 1);
        assert_eq!(decision.entries[0].package, exact);
    }
}

