mod common;

use callisto_cli::cli::{AddArgs, GlobalArgs, OutputFormat, VersionArgs};
use callisto_cli::commands;

use common::setup_polyglot_git_repo;

/// Two `version` runs with nothing committed between them must refuse the second (E121), not stack a second bump.
#[test]
fn test_version_twice_without_commit_is_refused_as_partial_run() {
    let dir = setup_polyglot_git_repo();
    let root = dir.path();

    let global = GlobalArgs {
        format: OutputFormat::Json,
        cwd: root.to_path_buf(),
        dry_run: false,
    };

    callisto_fixtures::scaffold_callisto(&global.cwd);

    commands::add::handle(
        AddArgs {
            packages: vec!["core-crate:patch".to_string()],
            summary: Some("Fix the frobnication bug".to_string()),
        },
        &global,
    )
    .unwrap();

    commands::version::handle(
        VersionArgs {
            refresh_lockfiles: false,
            no_refresh_lockfiles: true,
            strict: false,
            allow_empty_changesets: false,
            emit_decision: None,
        },
        &global,
    )
    .expect("the first version run must succeed and stage its changes");

    let second = commands::version::handle(
        VersionArgs {
            refresh_lockfiles: false,
            no_refresh_lockfiles: true,
            strict: false,
            allow_empty_changesets: false,
            emit_decision: None,
        },
        &global,
    );

    assert!(
        second.is_err(),
        "a second `version` run with nothing committed since the first must be refused, not \
         silently apply a second bump on top of the first uncommitted one"
    );
    let message = second.unwrap_err().to_string();
    assert!(
        message.contains("this looks like a `version` run that wrote and staged its changes but never committed")
            || message.contains("E121"),
        "expected the partial-run (E121) refusal, got: {message}"
    );
}
//! A repository whose root is one package (no workspace manifest) is a valid Callisto root.

use std::fs;
use std::path::Path;
use std::process::ExitCode;

use callisto_cli::cli::{
    AddArgs, GlobalArgs, InitArgs, InitVersioning, OutputFormat, ReleaseCommandArgs, StatusArgs, VersionArgs,
};
use callisto_cli::commands;
use callisto_fixtures::git::{init_repo, run_git};

fn repo(files: &[(&str, &str)]) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    for (path, content) in files {
        let path = dir.path().join(path);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, content).unwrap();
    }
    init_repo(dir.path());
    run_git(
        dir.path(),
        &["remote", "add", "origin", "https://github.com/example/single.git"],
    );
    run_git(dir.path(), &["add", "."]);
    run_git(dir.path(), &["commit", "-q", "-m", "initial"]);
    dir
}

fn global(cwd: &Path, dry_run: bool) -> GlobalArgs {
    GlobalArgs {
        format: OutputFormat::Json,
        cwd: cwd.to_path_buf(),
        dry_run,
    }
}

fn init(cwd: &Path) {
    let args = InitArgs {
        yes: true,
        versioning: Some(InitVersioning::Independent),
        ..Default::default()
    };
    assert_eq!(
        commands::init::handle(args, &global(cwd, false)).unwrap(),
        ExitCode::SUCCESS
    );
}

/// init, add, status (from a subdirectory), version, then release --dry-run.
fn lifecycle(dir: &tempfile::TempDir, package: &str, manifest: &str, bumped: &str) {
    let root = dir.path();
    init(&root.join("src"));
    assert!(root.join("callisto.toml").exists());
    assert!(!root.join("src/callisto.toml").exists());

    commands::add::handle(
        AddArgs {
            packages: vec![format!("{package}:minor")],
            summary: Some("Add a feature".to_owned()),
        },
        &global(root, false),
    )
    .unwrap();
    let status = StatusArgs {
        strict: false,
        check: false,
    };
    assert_eq!(
        commands::status::handle(status, &global(&root.join("src"), false)).unwrap(),
        ExitCode::SUCCESS
    );
    let version = VersionArgs {
        refresh_lockfiles: false,
        no_refresh_lockfiles: true,
        strict: false,
        allow_empty_changesets: false,
        emit_decision: None,
    };
    commands::version::handle(version, &global(root, false)).unwrap();
    assert!(fs::read_to_string(root.join(manifest)).unwrap().contains(bumped));

    run_git(root, &["add", "."]);
    run_git(root, &["commit", "-q", "-m", "version"]);
    let release = ReleaseCommandArgs {
        command: None,
        packages: vec![],
        receipt: None,
    };
    assert_eq!(
        commands::release::handle(release, &global(root, true)).unwrap(),
        ExitCode::SUCCESS
    );
}

#[test]
fn single_crate_repository() {
    let dir = repo(&[
        (
            "Cargo.toml",
            "[package]\nname = \"solo\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        ),
        ("src/lib.rs", "\n"),
    ]);
    lifecycle(&dir, "solo", "Cargo.toml", "version = \"0.2.0\"");
}

#[test]
fn single_npm_package_repository() {
    let dir = repo(&[
        (
            "package.json",
            "{\n  \"name\": \"solo\",\n  \"version\": \"0.1.0\"\n}\n",
        ),
        ("src/index.js", "\n"),
    ]);
    lifecycle(&dir, "solo", "package.json", "\"version\": \"0.2.0\"");
}

#[test]
fn single_python_package_repository_initializes() {
    let dir = repo(&[
        ("pyproject.toml", "[project]\nname = \"solo\"\nversion = \"0.1.0\"\n"),
        ("src/solo/__init__.py", "\n"),
    ]);
    init(&dir.path().join("src"));
    assert!(dir.path().join("callisto.toml").exists());
}

