        match err {
            GraphError::ReleaseCommand {
                program,
                failure: CommandFailure::MalformedOutput { .. },
                ..
            } => assert_eq!(program, "git"),
            other => panic!("expected ReleaseCommand{{failure: MalformedOutput}}, got {other:?}"),
        }
    }

