                let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
                ws_res.write_version(&bump.to, permit)?;
                ws_res.persist(permit)?;
                modified_paths.push(root_manifest.clone());
            }
        }
    }
}

